733	/// Returns the interval for the blinking cursor in milliseconds.
734	fn cursorBlinkInterval() u64 {
735	    if (std.valgrind.runningOnValgrind() > 0) {
736	        // If we're running under Valgrind, the cursor blink adds enough
737	        // churn that it makes some stalls annoying unless you're on a
738	        // super powerful computer, so we delay it.
739	        //
740	        // This is a hack, we should change some of our cursor timer
741	        // logic to be more efficient:
742	        // https://github.com/ghostty-org/ghostty/issues/8003
743	        return CURSOR_BLINK_INTERVAL * 5;
744	    }
745	
746	    return CURSOR_BLINK_INTERVAL;
747	}
