    58	/// This is the block type used for the addCompletedHandler callback.
    59	const CompletionBlock = objc.Block(struct {
    60	    renderer: *Renderer,
    61	    target: *Target,
    62	    sync: bool,
    63	}, .{
    64	    objc.c.id, // MTLCommandBuffer
    65	}, void);
