  1368	    /// image with no remaining placement. Unlike protocol d=A, a terminal
  1369	    /// clear also reclaims images that were already unplaced.
  1370	    pub fn clearScreen(
  1371	        self: *ImageStorage,
  1372	        io: std.Io,
  1373	        alloc: Allocator,
  1374	        t: *terminal.Terminal,
  1375	    ) void {
  1376	        const placements_before = self.placements.count();
  1377	        const images_before = self.images.count();
  1378	
  1379	        // Delete unused placements and images. Orphaned relative
  1380	        // placements must be reaped before the image sweep so that
  1381	        // their images are reclaimable too.
  1382	        self.deleteVisiblePlacements(alloc, t, true);
  1383	        _ = self.removeOrphans(t.screens.active, null);
  1384	        var image_it = self.images.iterator();
  1385	        while (image_it.next()) |entry| {
  1386	            self.deleteIfUnused(alloc, entry.key_ptr.*);
  1387	        }
  1388	
  1389	        // Mark mutated only if things changed.
  1390	        if (self.placements.count() != placements_before or
  1391	            self.images.count() != images_before) self.markMutated(io);
  1392	    }
