    70	    /// Upload any images to the GPU that need to be uploaded,
    71	    /// and remove any images that are no longer needed on the GPU.
    72	    ///
    73	    /// If any uploads fail, they are ignored. The return value
    74	    /// can be used to detect if upload was a total success (true)
    75	    /// or not (false).
    76	    pub fn upload(
    77	        self: *State,
    78	        alloc: Allocator,
    79	        api: *GraphicsAPI,
    80	    ) bool {
    81	        var success: bool = true;
    82	        var image_it = self.images.iterator();
    83	        while (image_it.next()) |kv| {
    84	            const img = &kv.value_ptr.image;
    85	            if (img.isUnloading()) {
    86	                img.deinit(alloc);
    87	                self.images.removeByPtr(kv.key_ptr);
    88	                continue;
    89	            }
    90	
    91	            if (img.isPending()) {
    92	                img.upload(
    93	                    alloc,
    94	                    api,
    95	                ) catch |err| {
    96	                    log.warn("error uploading image to GPU err={}", .{err});
    97	                    success = false;
    98	                };
    99	            }
   100	        }
   101	
   102	        return success;
   103	    }
