  1045	            pub fn deinit(self: *LatestFrame, io: std.Io) void {
  1046	                if (comptime ExportedFrame == void) return;
  1047	
  1048	                self.mutex.lockUncancelable(io);
  1049	                defer self.mutex.unlock(io);
