  7389	    return switch (tag) {
  7390	        .screen, .active => last: {
  7391	            const node = self.pages.last.?;
  7392	            break :last .{
  7393	                .node = node,
  7394	                .y = node.rows() - 1,
  7395	                .x = node.cols() - 1,
  7396	            };
  7397	        },
  7398	
  7399	        .viewport => viewport: {
  7400	            var br = self.getTopLeft(.viewport);
  7401	            br = br.down(self.rows - 1).?;
  7402	            br.x = br.node.cols() - 1;
